class SecureDevice
  def initialize(key, io)
    @key, @io, @prev, @seq = key, io, "".b, 1
  end
  def write(line)
    body = canonical(line)                          # redact; stable field order
    @prev = OpenSSL::HMAC.digest("SHA256", @key, @prev + [@seq].pack("Q>") + body)
    @io.write("#{@prev.unpack1("H*")} #{body}"); @io.fsync if @io.respond_to?(:fsync)
    @seq += 1
  end
end
